const item = $('When Executed by Another Workflow').first().json;

let origen = item.origen || null;

// Limpia GrupoCaptura
let grupoCaptura = item.GrupoCaptura != null
  ? String(item.GrupoCaptura).trim()
  : null;

// Mapeo de grupos de captura
if (grupoCaptura === "9165") {
  grupoCaptura = "SALTA";
} else if (grupoCaptura === "9151") {
  grupoCaptura = "JUJUY";
}

// ===== SOBREESCRIBE GrupoCaptura SEGÚN PREFIJO TELEFÓNICO =====

// Deja sólo números
let numero = String(item.number || "").replace(/\D/g, "");

// Elimina prefijo país
if (numero.startsWith("549")) {
  numero = numero.slice(3);
} else if (numero.startsWith("54")) {
  numero = numero.slice(2);
}

// Prefijos
const prefijosSalta = ["387"];
const prefijosJujuy = ["388"];

// Default: TUCUMAN
if (prefijosSalta.some(prefijo => numero.startsWith(prefijo))) {
  grupoCaptura = "SALTA";
} else if (prefijosJujuy.some(prefijo => numero.startsWith(prefijo))) {
  grupoCaptura = "JUJUY";
} else {
  grupoCaptura = "TUCUMAN";
}

return [{
  json: {
    ...item,
    origen,
    GrupoCaptura: grupoCaptura
  }
}];

const item = $('PDA').first().json.body; // Cambiá "Webhook" por el nombre de tu nodo

// =========================
// ORIGEN
// =========================
let origen = item.origen || item.origin || null;

// =========================
// INTERÉS
// =========================
const interesMap = {
  "bajo": "3",
  "medio": "07B7AC5A",
  "alto": "2D43E90C"
};

const codigosValidos = [
  "3",
  "07B7AC5A",
  "2D43E90C"
];

const comentario = (item.notes || "")
  .replace(/\r?\n/g, " - ")
  .replace(/\s*-\s*/g, " - ")
  .trim();

let interes = item.interes;

// Si no viene, usar Medio por defecto
if (!interes) {
  interes = "07B7AC5A";
} else {
  const valor = interes.toString().trim();

  if (codigosValidos.includes(valor)) {
    interes = valor;
  } else {
    interes = interesMap[valor.toLowerCase()] ?? "07B7AC5A";
  }
}

// =========================
// GRUPO CAPTURA
// =========================
let grupoCaptura = item.GrupoCaptura != null
  ? String(item.GrupoCaptura)
  : null;

// Mapeo por código
if (grupoCaptura === "9165") {
  grupoCaptura = "SALTA";
} else if (grupoCaptura === "9151") {
  grupoCaptura = "JUJUY";
}

// =========================
// POR PREFIJO TELEFÓNICO
// =========================
let numero = (item.number || item.tel || "").replace(/\D/g, "");

// Elimina país
if (numero.startsWith("54")) {
  numero = numero.slice(2);
}

// Elimina el 9 de celulares
if (numero.startsWith("9")) {
  numero = numero.slice(1);
}

const prefijosSalta = [
  "3868",
  "3873",
  "3876",
  "3878",
  "3877",
  "387"
];

const prefijosJujuy = [
  "388",
  "3886",
  "3889",
  "3888",
  "3885"
];

if (prefijosSalta.some(prefijo => numero.startsWith(prefijo))) {
  grupoCaptura = "Salta";
} else if (prefijosJujuy.some(prefijo => numero.startsWith(prefijo))) {
  grupoCaptura = "Jujuy";
} else {
  grupoCaptura = "Todos";
}

return [
  {
    json: {
      ...item,
      origen,
      comentario,
      GrupoCaptura: grupoCaptura,
      interes
    }
  }
];

const items = $("When Executed by Another Workflow").all();

const interesMap = {
  "bajo": "3",
  "medio": "07B7AC5A",
  "alto": "2D43E90C",
};

return items.map(item => {
  const data = { ...item.json };

  if (typeof data.interes === "string") {
    const key = data.interes.trim().toLowerCase();

    if (interesMap[key]) {
      data.interes = interesMap[key]?? "07B7AC5A";
    }
  }

  return {
    json: data,
  };
});

